import { Worker } from 'worker_threads';

export default class CsvDownloaderService {
  downloadCsv(url) {
    const worker = new Worker('./workers/csv-downloader-worker.js', {
      workerData: { url },
    });

    worker.on('message', (event) => {
      console.log('Received message from worker:', event);
    });

    worker.on('error', (event) => {
      console.error('Error in worker:', event);
    });

    worker.on('exit', (code) => {
      console.log(`Worker exited with code ${code}`);
    });
  }
}
